def create_template(apps, schema_editor):
    Template = apps.get_model("migration_portal", "ChecklistTemplate")
    Item = apps.get_model("migration_portal", "ChecklistTemplateItem")
    template, created = Template.objects.get_or_create(
        name=TEMPLATE_NAME,
        defaults={"description": (
            "Базовый перечень для подготовки исходных данных по предпроектной "
            "(предынвестиционной) документации в Республике Беларусь. Перечень "
            "ориентирован на СП 1.02.01-2023 (с Изменением № 1, действующим с 01.03.2026), "
            "Указ Президента № 26 от 14.01.2014 и статью 69 Кодекса об архитектурной, "
            "градостроительной и строительной деятельности. Не все пункты требуются "
            "для каждого объекта: состав уточняется по назначению, классу сложности, "
            "виду строительства, разрешительной документации и применимым нормам."
        )},
    )
    if created:
        Item.objects.bulk_create([
            Item(template=template, title=title, description=description, sort_order=index)
            for index, (title, description) in enumerate(ITEMS)
        ])


def remove_template(apps, schema_editor):
    apps.get_model("migration_portal", "ChecklistTemplate").objects.filter(name=TEMPLATE_NAME).delete()


class Migration(migrations.Migration):
    dependencies = [("migration_portal", "0005_project_stage")]
    operations = [migrations.RunPython(create_template, remove_template)]
